#!/bin/bash

[ -f "$0" ] || { echo "Cannot run as dot command." >&2; kill -INT $$; }

# Define variables and constants.
RCM_EXTENSION_VERSION=0.19.0-alpha.14

# Usage Functions.
usage() {
    cat << EOF
Usage: rcm require <owner>/<repo> [version]

Global Options:
   --version
        Print version of this script.
   --help
        Show this help.
EOF

}

[ -f "${RCM_LIB}/require.sh" ] && source "${RCM_LIB}/require.sh" || { usage >&2; exit 1; }

# Parse arguments. Generated by parse-options.sh
_new_arguments=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        --help) help=1; shift ;;
        --version) version=1; shift ;;
        --here) here=1; shift ;;
        --package=*) package="${1#*=}"; shift ;;
        --package) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then package="$2"; shift; fi; shift ;;
        --package-version=*) package_version="${1#*=}"; shift ;;
        --package-version) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then package_version="$2"; shift; fi; shift ;;
        --) shift
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
        --[^-]*) shift ;;
        *) _new_arguments+=("$1"); shift ;;
    esac
done
set -- "${_new_arguments[@]}"
unset _new_arguments

# Help and Version.
[ -n "$help" ] && { usage; exit 0; }
[ -n "$version" ] && { e $RCM_EXTENSION_VERSION; x; }

# ------------------------------------------------------------------------------

# Title.
title rcm require
____

# Dependency.

# Functions.
# Mapping operand to value of options.
chapter Mapping operand as value of options.
if [ -n "$1" ];then
    code --package=$1
    package=$1; shift
fi
if [ -n "$1" ];then
    code --package-version=$1
    package_version=$1; shift
fi
____

# Requirement, validate, and populate value.
chapter Variable dump.
if [ -z "$package" ];then
    error "Argument --package required."; x
fi
if [[ ! "$package" =~ / ]];then
    error "The format of --package is not correct."; x
fi
code here=$
code package=$
url="https://github.com/${package}"
code url=$
____

if [ -n "$here" ];then

    # Dependency.
    require vendor/ijortengab/rcm/functions/classes/rcm-dir.sh
    require vendor/ijortengab/rcm/functions/utility/link-symbolic.sh
    require vendor/ijortengab/rcm/functions/utility/link-symbolic-dir.sh

    chapter Memeriksa current working direktori.
    path="${PWD}/rcm/install"
    code path=$
    rcm-dir terminateIfNotExists "$path"
    ____

    chapter Memeriksa direktori commands.
    target="${RCM_LIB}/commands"
    code target="$target"
    source="${PWD}/rcm/install/commands"
    code source="$source"
    rcm-dir isExists "$source"
    if [ -n "$found" ];then
        __ Symlink all items inside commands directory.
        ____
        while IFS= read -r line; do
            link-symbolic-dir "${source}/${line}" "${target}/${line}" - absolute
        done <<< `ls -1 "$source"`
    else
        ____
    fi

    chapter Memeriksa direktori interfaces.
    target="${RCM_LIB}/interfaces"
    code target="$target"
    source="rcm/install/interfaces"
    code source="$source"
    rcm-dir isExists "$source"
    if [ -n "$found" ];then
        __ Symlink all items inside interfaces directory.
        ____

        while IFS= read -r line; do
            link-symbolic "${PWD}/${line}" "${target}${line/$source/}" - absolute
        done <<< `find "$source" -type f`
    else
        ____
    fi

    chapter Memeriksa direktori vendor.
    source="${PWD}"
    target="${RCM_LIB}/vendor/${package}"
    code source=$
    code target=$
    target_parent=$(dirname "$target")
    code mkdir -p "$target_parent"
    mkdir -p "$target_parent"
    cd "$target_parent"
    code ln -sf "$source" "$target"
    ln -sf "$source"
    ____

else

    # Dependency.
    require rcm install

    INDENT+="    " \
    rcm install \
        --url="$url" \
        --extension-version="$package_version" \
        ; [ ! $? -eq 0 ] && x

    cat << EOF >> "${RCM_LIB}/require.txt"
$package $package_version
EOF

fi

